import qs from "qs";
import * as auth from "../auth-provider";
import { useAuth } from "../context/auth-context";
import { useCallback } from "react";

const apiUrl = process.env.REACT_APP_API_URL;
interface Config extends RequestInit {
  data?: object;
  token?: string;
}

export const http = async (
  endpoint: string,
  { data, token, headers, ...customConfig }: Config = {}, //给第二个参数加默认值，表示有没有传都可以
) => {
  const config = {
    method: "GET", //默认为get
    headers: {
      Authorization: token ? `Bearer ${token}` : "",
      "Content-Type": data ? "application/json" : "",
    },

    ...customConfig, //但如果后面customConfig传入的为post就被覆盖为post
  };

  if (config.method.toUpperCase() === "GET") {
    //get请求里面，所传的参数要带到url里面
    endpoint += `?${qs.stringify(data)}`;
  } else {
    config.body = JSON.stringify(data || {});
  }
  return window
    .fetch(`${apiUrl}/${endpoint}`, config)
    .then(async (response) => {
      if (response.status === 401) {
        //401退出登录
        await auth.logout();
        window.location.reload();
        // 401也要抛出错误，否则Promise会走向成功
        return Promise.reject(new Error("请重新登录"));
      }
      const data = await response.json();
      if (response.ok) {
        return data;
      } else {
        // ✅包装成真正Error实例，而不是普通对象
        return Promise.reject(new Error(data?.message || "请求出错"));
      }
    });
};

//每次组件渲染都返回一个新的函数，要用useCallback包裹起来
export const useHttp = () => {
  const { user } = useAuth();
  return useCallback(
    (...[endpoint, config]: Parameters<typeof http>) =>
      http(endpoint, { ...config, token: user?.token }),
    [user?.token],
  );
  // 把token自动加入http请求)
};
