import { Update } from "@reduxjs/toolkit";
import React, { ProfilerOnRenderCallback, ProfilerProps } from "react";

type Props = { metadata?: any; phases?: ("mount" | "update")[] } & Omit<
  ProfilerProps,
  "onRender"
>;

let quene: unknown[] = [];
const sendPropfileQuene = () => {
  if (!quene.length) {
    return;
  }
  const queneToSend = [...quene];
  quene = [];
  console.log(queneToSend);
};
setInterval(sendPropfileQuene, 5000);

export const Profiler = ({ metadata, phases, ...props }: Props) => {
  const reportProfile: ProfilerOnRenderCallback = (
    id: string,
    phase: "mount" | "update" | "nested-update",
    actualDuation: number,
    baseDuration: number,
    startTime: number,
    commitTime: number,
  ) => {
    if (!phases || phase.includes(phase)) {
      quene.push({
        id,
        phase,
        actualDuation,
        baseDuration,
        startTime,
        commitTime,
        metadata,
      });
    }
  };
  return <React.Profiler onRender={reportProfile} {...props} />;
};
